/** Test-only child process. IPC inputs are generated by the disposable lab.
 * No test controls are exposed by the production application/router. */
import { startLinkFixture, type LinkFixtureConfig } from './managedSymlinkRecovery.runtime';
import {
	ManagedSftpRepositorySession,
	type ManagedRepositorySessionProvider,
} from '../../src/utils/restic/ManagedSftpRepositorySession';
import { ManagedExportStore } from '../../src/stores/ManagedExportStore';
import { ManagedExportService } from '../../src/services/ManagedExportService';
import { ManagedExportController } from '../../src/controllers/ManagedExportController';
import { createManagedExportRouter } from '../../src/routes/managedExports';
import {
	exportConfiguration,
	TemporaryExportError,
} from '../../src/utils/managedExport/ExportPolicy';
import { S3ExportStorage } from '../../src/utils/managedExport/S3ExportStorage';
import { assertExportIsolation } from '../../src/utils/managedExport/ExportIsolation';
let running: Awaited<ReturnType<typeof startLinkFixture>> | undefined,
	service: ManagedExportService | undefined,
	store: ManagedExportStore | undefined,
	archiveReads = 0,
	timer: ReturnType<typeof setInterval>;
const storageDiagnostics: any[] = [];
const instances: S3ExportStorage[] = [];
const timings = {
	metadataMs: [] as number[],
	archiveMs: [] as number[],
	uploadMs: [] as number[],
	readbackMs: [] as number[],
};
let activeSessions = 0,
	maxSessions = 0;
process.on('message', async (message: any) => {
	try {
		if (message.action === 'start') {
			const config = message.config as LinkFixtureConfig;
			const native = new ManagedSftpRepositorySession();
			const sessions: ManagedRepositorySessionProvider = {
				withSession: (access, consume, signal, limits) =>
					native.withSession(
						access,
						session =>
							consume({
								...session,
								archive: async (...args: Parameters<typeof session.archive>) => {
									archiveReads++;
									process.send?.({ event: 'source-archive' });
									const began = performance.now();
									try {
										return await session.archive(...args);
									} finally {
										timings.archiveMs.push(Math.round(performance.now() - began));
									}
								},
								streamFiles: async (...args: Parameters<typeof session.streamFiles>) => {
									const began = performance.now();
									try {
										return await session.streamFiles(...args);
									} finally {
										timings.metadataMs.push(Math.round(performance.now() - began));
									}
								},
							}),
						signal,
						limits
					),
			};
			running = await startLinkFixture(config, sessions);
			store = new ManagedExportStore(message.file);
			const factory = (configuration: NonNullable<ReturnType<typeof exportConfiguration>>) => {
				const storage = new S3ExportStorage(configuration);
				const upload = storage.upload.bind(storage),
					verify = storage.verify.bind(storage);
				storage.upload = async (...args) => {
					const began = performance.now();
					try {
						return await upload(...args);
					} finally {
						timings.uploadMs.push(Math.round(performance.now() - began));
					}
				};
				storage.verify = async (...args) => {
					const began = performance.now();
					try {
						return await verify(...args);
					} finally {
						timings.readbackMs.push(Math.round(performance.now() - began));
					}
				};
				instances.push(storage);
				const close = storage.close.bind(storage);
				storage.close = () => {
					storageDiagnostics.push(storage.diagnostics());
					close();
				};
				if (message.fault === 'hold-upload' || message.fault === 'upload-error') {
					const send = storage.client.send.bind(storage.client);
					let parts = 0;
					(storage.client as any).send = async (command: any, options: any) => {
						if (
							command.constructor.name === 'UploadPartCommand' &&
							command.input.Key.endsWith('.tar') &&
							++parts === 2
						) {
							process.send?.({ event: 'held', phase: 'upload' });
							if (message.fault === 'upload-error')
								throw new TemporaryExportError('storage-unavailable');
							await new Promise<void>((_resolve, reject) =>
								options.abortSignal.addEventListener(
									'abort',
									() => reject(new TemporaryExportError('interrupted')),
									{ once: true }
								)
							);
						}
						return send(command, options);
					};
				}
				if (message.fault === 'hold-verify')
					storage.verify = async (_job, signal) => {
						process.send?.({ event: 'held', phase: 'verify' });
						await new Promise<void>((_resolve, reject) =>
							signal.addEventListener(
								'abort',
								() => reject(new TemporaryExportError('interrupted')),
								{ once: true }
							)
						);
					};
				return storage;
			};
			service = new ManagedExportService(
				store,
				running.recovery,
				exportConfiguration,
				async c => assertExportIsolation(c, []),
				factory
			);
			running.app.use(
				'/api/backups',
				createManagedExportRouter(new ManagedExportController(service))
			);
			await service.recoverInterrupted();
			timer = setInterval(() => void service!.tick(), 250);
			timer.unref();
			process.send?.({ event: 'started', base: running.base });
		} else if (message.action === 'stats')
			process.send?.({
				event: 'stats',
				archiveReads,
				timings,
				storageDiagnostics: instances.map(s => s.diagnostics()),
				nodePeakRssBytes: process.resourceUsage().maxRSS * 1024,
				sourceIndex: [
					...((running!.recovery as any).indexes.entries as Map<string, any>).values(),
				].map(e => ({ entries: e.count, bytes: e.bytes, reason: e.error?.reason })),
				jobs: store!.all().map(j => ({
					id: j.id,
					state: j.state,
					failureStage: j.failureStage,
					failureDetail: j.failureDetail,
					cleaned: j.cleaned,
					cleanupAttempts: j.cleanupAttempts,
					reservedBytes: j.reservedBytes,
				})),
			});
		else if (message.action === 'expire') {
			store!.update(message.id, { expiresAt: Date.now() - 1 });
			await service!.tick();
			process.send?.({ event: 'expired' });
		} else if (message.action === 'short-authorization') {
			const storage = new S3ExportStorage(exportConfiguration()!);
			try {
				process.send?.({
					event: 'short-authorization',
					url: await storage.authorize(store!.get(message.id)!, 1),
				});
			} finally {
				storage.close();
			}
		} else if (message.action === 'stop') {
			clearInterval(timer);
			await service?.shutdown();
			await running?.close();
			process.send?.({ event: 'stopped' });
			process.disconnect();
		}
	} catch {
		process.send?.({ event: 'fixture-error' });
	}
});
